std::vector<int> src = {10, 20, 30, 40};

// 1. Copy Construction (Exact Match)
std::vector<int> full_copy(src);

// 2. Range Constructor (Subset)
// Copies elements [begin, end - 2) -> {10, 20}
std::vector<int> subset(src.begin(), src.end() - 2);

// 3. Inter-container Copy (Vector to List)
std::list<int> l(src.begin(), src.end());

// 4. Copy via Assignment Operator
std::vector<int> assigned_copy;
assigned_copy = src;

// 5. Using back_inserter (for pre-existing containers)
std::vector<int> dest;
std::copy(src.begin(), src.end(),
          std::back_inserter(dest));

// 6. Initializer List Construction
std::set<int> my_set = {10, 5, 20};
